async function refreshWalk(id:string){try{setShared(await api('walks/'+id))}catch(e:any){notify(e.message)}}
function save(r:Route){setState(s=>({...s,saved:s.saved.includes(r.id)?s.saved.filter(x=>x!==r.id):[...s.saved,r.id]}))}
async function route(r:Route){const seq=++routeSeq.current;if(r.custom)setState(s=>({...s,custom:s.custom.some(x=>x.id===r.id)?s.custom:[...s.custom,r]}));setSelected(r);setSunset('');setRouteData(null);setLoading('Finding walking directions…');try{const d=await api('route?points='+encodeURIComponent(JSON.stringify(r.points)));if(seq===routeSeq.current){setRouteData(d);if(r.custom)setState(s=>({...s,custom:s.custom.map(x=>x.id===r.id?{...x,distance:d.distance/1000,minutes:Math.round(d.duration/60)}:x)}))}}catch(e:any){if(seq===routeSeq.current){try{const cached=JSON.parse(localStorage.getItem('flaneur-route-'+r.id)??'null');if(cached){setRouteData(cached);notify('Showing downloaded directions. Conditions may have changed.')}else notify(e.message)}catch{notify(e.message)}}}finally{if(seq===routeSeq.current)setLoading('')}}
async function locate(){if(!navigator.geolocation){notify('Location is unavailable on this device. Search for an area instead.');setModal('search');return}setLoading('Finding your area…');navigator.geolocation.getCurrentPosition(p=>{const c=[p.coords.latitude,p.coords.longitude];setCenter(c);const town=haversine(c,[51.374,-.100])<8000?'Croydon':area;setArea(town);setState(s=>({...s,location:{center:c,area:town}}));setSelected(null);setRouteData(null);setPlaces([]);discover(c,placeCategory,town)},()=>{setLoading('');notify('Location was not available. Enter your town or postcode instead.');setModal('search')},{timeout:12000,maximumAge:60000})}
